import unittest

from hourglass.rounding import (
    span_label,
    rounded_labels,
    round_span,
    round_minutes
)
from hourglass.parsing import parse_span
from hourglass.models import Span

class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_minutes(100, step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)

    def test_good_steps_are_accepted(self):
        for step in (1, 5, 15, 30, 60):
            self.assertEqual(round_minutes(120, step), 120)

class RoundTests(unittest.TestCase):
    def test_rounds_to_nearest(self):
        self.assertEqual(round_minutes(62, 15), 60)
        self.assertEqual(round_minutes(68, 15), 75)

    def test_halves_go_up(self):
        self.assertEqual(round_minutes(15, 30), 30)
        self.assertEqual(round_minutes(14, 30), 0)

    def test_span_rounds_both_ends(self):
        result = round_span(parse_span("08:58-17:12"), 15)
        self.assertEqual(result, parse_span("09:00-17:15"))

    def test_collapsing_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(601, 604), 15)

    def test_end_of_day_stays_valid(self):
        self.assertEqual(round_span(Span(0, 1439), 30), Span(0, 1440))

class LabelTests(unittest.TestCase):
    def test_label_format(self):
        label = span_label(parse_span("09:00-17:15"))
        self.assertEqual(label, "09:00-17:15 (8h 15m)")

    def test_labels_in_order(self):
        spans = [parse_span("08:58-12:03"), parse_span("13:01-17:14")]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["09:00-12:00 (3h 0m)", "13:00-17:15 (4h 15m)"]
        )
